// fast exponentiation
int64 modpow(int64 a, int64 e) {
    int64 res = 1;
    while (e) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, A, B;
    cin >> H >> W >> A >> B;

    int N = H + W;
    vector<int64> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; i++) fact[i] = fact[i-1] * i % MOD;
    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = N; i >= 1; i--) invfact[i-1] = invfact[i] * i % MOD;

    auto nCr = [&](int n, int r) -> int64 {
        if (r < 0 || r > n) return 0;
        return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
    };

    int64 ans = 0;
    // we go from (0,0) to (H-A-1, B-1+i) then down/right around the block
    for (int i = B; i < W; i++) {
        int r1 = H - A - 1;
        int c1 = i;
        // paths from start to (r1, c1)
        int64 part1 = nCr(r1 + c1, r1);

        int r2 = A;
        int c2 = W - 1 - i;
        // paths from (r1+1, c1) to (H-1, W-1) = from (0,0) to (r2-1, c2)
        if (r2 > 0) {
            int64 part2 = nCr(r2 - 1 + c2, r2 - 1);
            ans = (ans + part1 * part2) % MOD;
        }
    }

    cout << ans % MOD << "\n";
    return 0;
}

