const int MOD = 1e9 + 7;
const int MAXN = 2e5 + 5; // H+W can be up to... need to know constraints

// Need to compute combinations C(n, k)
// n can be up to H+W-2 which could be large
// Let's precompute factorials up to some limit

long long fact[300005], inv_fact[300005];

long long power(long long a, long long b, long long mod) {
    long long res = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void precompute(int n) {
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    inv_fact[n] = power(fact[n], MOD-2, MOD);
    for (int i = n-1; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;
}

long long C(int n, int k) {
    if (k < 0 || k > n || n < 0) return 0;
    return fact[n] % MOD * inv_fact[k] % MOD * inv_fact[n-k] % MOD;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int H, W, A, B;
    cin >> H >> W >> A >> B;

    precompute(H + W + 5);

    if (A == 0 || B == 0) {
        cout << C(H+W-2, H-1) << endl;
        return 0;
    }

    if (H - A == 0) {
        // A = H, start is in forbidden region if B >= 1
        cout << 0 << endl;
        return 0;
    }

    long long ans = 0;
    for (int c = B+1; c <= W; c++) {
        // paths (1,1) to (H-A, c): C(H-A+c-2, c-1)
        // paths (H-A+1, c) to (H, W): C(A-1+W-c, W-c)
        long long ways1 = C(H-A+c-2, c-1);
        long long ways2 = C(A-1+W-c, W-c);
        ans = (ans + ways1 % MOD * ways2 % MOD) % MOD;
    }

    cout << ans << endl;
    return 0;
}

