    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();

        int n = H + W + 5;
        long[] fact = new long[n];
        long[] invFact = new long[n];
        fact[0] = 1;
        for (int i = 1; i < n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n - 1] = modPow(fact[n - 1], MOD - 2);
        for (int i = n - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        long ans = 0;

        // Split at boundary between safe upper area and forbidden lower-left area.
        // Choose the crossing point on row H-A, columns B..W-1 (1-indexed).
        for (int c = B; c <= W - 1; c++) {
            long ways1 = comb((H - A - 1) + c, c, fact, invFact);
            long ways2 = comb((A - 1) + (W - 1 - c), A - 1, fact, invFact);
            ans = (ans + ways1 * ways2) % MOD;
        }

        System.out.println(ans);
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

MOD = 10**9 + 7

def modinv(a):
    return pow(a, MOD - 2, MOD)

def prepare_factorials(n):
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD
    invfact[n] = modinv(fact[n])
    for i in range(n, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD
    return fact, invfact

def comb(n, k, fact, invfact):
    if k < 0 or k > n:
        return 0
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

def solve():
    H, W, A, B = map(int, input().split())
    fact, invfact = prepare_factorials(H + W)

    res = 0
    for i in range(B, W):
        # path from (0,0) to (H-A-1, i)
        ways1 = comb(H - A - 1 + i, i, fact, invfact)
        # path from (H-A, i) to (H-1, W-1)
        ways2 = comb(A - 1 + W - 1 - i, A - 1, fact, invfact)
        res = (res + ways1 * ways2) % MOD
    print(res)

if __name__ == "__main__":
    solve()
